module glitch_free_mux (
    input  wire clk1,
    input  wire clk2,
    input  wire sel,
    input  wire rst_n,
    output wire clkout
);
    reg en1, en2;
    reg sel_d1, sel_d2;
    reg [1:0] state;
    reg sel_chg;

    // Sample sel to detect change. 
    // Since sel is synchronous to one of the clocks, sampling on both ensures timely detection.
    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n) begin
            sel_d1 <= 1'b0;
            en1 <= 1'b0;
        end else begin
            sel_d1 <= sel;
        end
    end
    always @(posedge clk2 or negedge rst_n) begin
        if (!rst_n) sel_d2 <= 1'b0;
        else sel_d2 <= sel;
    end

    // Register sel change edge to avoid combinatorial glitches
    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n) sel_chg <= 1'b0;
        else sel_chg <= (sel != sel_d1) | (sel != sel_d2);
    end

    // Glitch-free switching FSM
    always @(posedge clk1 or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'd0;
        end else begin
            case (state)
                2'd0: begin // Idle: sel=0, clk1 active
                    en1 <= 1'b1;
                    en2 <= 1'b0;
                    if (sel_chg) state <= 2'd1;
                end
                2'd1: begin // Disable clk1 on next clk1 posedge
                    en1 <= 1'b0;
                    state <= 2'd2;
                end
                2'd2: begin // Enable clk2 on next clk2 posedge
                    en2 <= 1'b1;
                    state <= 2'd3;
                end
                2'd3: begin // Idle: sel=1, clk2 active
                    en1 <= 1'b0;
                    en2 <= 1'b1;
                    if (sel_chg) state <= 2'd4;
                end
                2'd4: begin // Disable clk2 on next clk2 posedge
                    en2 <= 1'b0;
                    state <= 2'd5;
                end
                2'd5: begin // Enable clk1 on next clk1 posedge
                    en1 <= 1'b1;
                    state <= 2'd0;
                end
            endcase
        end
    end

    assign clkout = (en1 & clk1) | (en2 & clk2);
endmodule

output.rtl/apb_dsp_unit.v:
`timescale 1ns / 1ps

module apb_dsp_unit (
    input wire pclk,
    input wire presetn,
    input wire [9:0] paddr,
    input wire pselx,
    input wire penable,
    input wire pwrite,
    input wire [7:0] pwdata,
    output reg pready,
    output reg [7:0] prdata,
    output reg pslverr,
    output reg sram_valid
);

localparam IDLE = 2'b00,
           READ_STATE = 2'b01,
           WRITE_STATE = 2'b10;

reg [1:0] pstate;
reg [2:0] addr_reg;

// Internal CSR registers
reg [7:0] r_operand_1;
reg [7:0] r_operand_2;
reg [1:0] r_Enable;
reg [7:0] r_write_address;
reg [7:0] r_write_data;
reg [7:0] result_reg;

// Address decoding for CSR space (0x00 to 0x05)
wire valid_addr = (paddr[2:0] >= 3'd0) && (paddr[2:0] <= 3'd5);

// Combinational DSP result computation
always @(*) begin
    case (r_Enable)
        2'd1: result_reg = r_operand_1 + r_operand_2;
        2'd2: result_reg = r_operand_1 * r_operand_2;
        default: result_reg = 8'd0;
    endcase
end

// Main APB State Machine & Register Logic
always @(posedge pclk or negedge presetn) begin
    if (!presetn) begin
        pstate          <= IDLE;
        addr_reg        <= 3'd0;
        prdata          <= 8'd0;
        pslverr         <= 1'b0;
        sram_valid      <= 1'b0;
        pready          <= 1'b1;
        r_operand_1     <= 8'd0;
        r_operand_2     <= 8'd0;
        r_Enable        <= 2'd0;
        r_write_address <= 8'd0;
        r_write_data    <= 8'd0;
    end else begin
        addr_reg  <= paddr[2:0];
        pready    <= 1'b1;
        sram_valid<= 1'b0;

        // APB Phase 1: Selection & Address Decoding
        if (pselx & !penable) begin
            pslverr <= valid_addr ? 1'b0 : 1'b1;
            if (pwrite) begin
                pstate <= WRITE_STATE;
            end else begin
                pstate <= READ_STATE;
            end
        end
        // APB Phase 2: Enable & Data Transfer
        else if (pselx & penable) begin
            if (pstate == READ_STATE) begin
                case (addr_reg)
                    3'd0: prdata <= r_operand_1;
                    3'd1: prdata <= r_operand_2;
                    3'd2: prdata <= r_Enable;
                    3'd3: prdata <= r_write_address;
                    3'd4: prdata <= r_write_data;
                    3'd5: prdata <= result_reg;
                    default: prdata <= 8'd0;
                endcase
            end else if (pstate == WRITE_STATE) begin
                case (addr_reg)
                    3'd0: r_operand_1 <= pwdata;
                    3'd1: r_operand_2 <= pwdata;
                    3'd2: r_Enable <= pwdata[1:0];
                    3'd3: r_write_address <= pwdata;
                    3'd4: r_write_data <= pwdata;
                    default: ;
                endcase
                // Assert sram_valid for one cycle when Data Writing mode was active
                if (r_Enable == 2'b11) begin
                    sram_valid <= 1'b1;
                end
            end
            pstate <= IDLE;
        end
    end
end

endmodule

output.rtl/cvdp_copilot_apb_gpio.sv:
`ifndef CVDPCOPILOT_APB_GPIO_SV
`define CVDPCOPILOT_APB_GPIO_SV

/// @brief APB GPIO Module with configurable width, bidirectional control, and interrupt generation
/// @details Implements a fully compliant Advanced Peripheral Bus (APB) interface for a 
///          configurable GPIO peripheral. Features include input synchronization, 
///          edge/level-sensitive interrupt configuration, polarity control, and 
///          robust reset behavior. No wait states are introduced (pready=1).
module cvdp_copilot_apb_gpio #(
    parameter int unsigned GPIO_WIDTH = 8
)(
    // APB Interface
    input  logic                  pclk,
    input  logic                  preset_n,
    input  logic                  psel,
    input  logic  [7:2]           paddr,
    input  logic                  penable,
    input  logic                  pwrite,
    input  logic  [31:0]          pwdata,

    // GPIO Signals
    input  logic  [GPIO_WIDTH-1:0] gpio_in,

    output logic  [31:0]          prdata,
    output logic                  pready,
    output logic                  pslverr,
    output logic  [GPIO_WIDTH-1:0] gpio_out,
    output logic  [GPIO_WIDTH-1:0] gpio_enable,
    output logic  [GPIO_WIDTH-1:0] gpio_int,
    output logic                  comb_int
);

    // =========================================================================
    // Internal Register Declarations
    // =========================================================================
    logic [31:0] reg_out_data;
    logic [31:0] reg_out_en;
    logic [31:0] reg_int_en;
    logic [31:0] reg_int_type;
    logic [31:0] reg_int_pol;

    // =========================================================================
    // Input Synchronization (2-Stage Flip-Flop for Metastability Mitigation)
    // =========================================================================
    logic [GPIO_WIDTH-1:0] sync_d1, sync_d2;

    always_ff @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            sync_d1 <= '0;
            sync_d2 <= '0;
        end else begin
            sync_d1 <= gpio_in;
            sync_d2 <= sync_d1;
        end
    end

    // =========================================================================
    // APB Read Logic
    // =========================================================================
    always_comb begin
        case (paddr[7:2])
            2'h0: prdata = {24'h0, sync_d2};              // 0x00: GPIO Input Data (RO)
            2'h1: prdata = {24'h0, reg_out_data[GPIO_WIDTH-1:0]}; // 0x04: GPIO Output Data
            2'h2: prdata = {24'h0, reg_out_en[GPIO_WIDTH-1:0]};   // 0x08: GPIO Output Enable
            2'h3: prdata = reg_int_en;                    // 0x0C: GPIO Interrupt Enable
            2'h4: prdata = reg_int_type;                  // 0x10: GPIO Interrupt Type
            2'h5: prdata = reg_int_pol;                   // 0x14: GPIO Interrupt Polarity
            2'h6: prdata = gpio_int;                      // 0x18: GPIO Interrupt State (RO)
            default: prdata = 32'h0;                      // Undefined Address
        endcase
    end

    // =========================================================================
    // APB Write Logic
    // =========================================================================
    always_ff @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            reg_out_data  <= '0;
            reg_out_en    <= '0;
            reg_int_en    <= '0;
            reg_int_type  <= '0;
            reg_int_pol   <= '0;
        end else if (psel & penable & pwrite) begin
            case (paddr[7:2])
                2'h1: reg_out_data  <= pwdata[GPIO_WIDTH-1:0];
                2'h2: reg_out_en    <= pwdata[GPIO_WIDTH-1:0];
                2'h3: reg_int_en    <= pwdata;
                2'h4: reg_int_type  <= pwdata;
                2'h5: reg_int_pol   <= pwdata;
                default: ; // Silently ignore writes to undefined/RO addresses
            endcase
        end
    end

    // =========================================================================
    // GPIO Output & Direction Control
    // =========================================================================
    assign gpio_out = reg_out_data[GPIO_WIDTH-1:0];
    assign gpio_enable = reg_out_en[GPIO_WIDTH-1:0];

    // =========================================================================
    // Interrupt Configuration & Generation
    // =========================================================================
    logic [GPIO_WIDTH-1:0] edge_latch;

    // Edge Detection Latch (Updates synchronously with clk)
    always_ff @(posedge pclk or negedge preset_n) begin
        if (!preset_n) begin
            edge_latch <= '0;
        end else begin
            edge_latch <= sync_d2;
        end
    end

    // Per-Pin Interrupt Logic
    generate
        for (genvar i = 0; i < GPIO_WIDTH; i++) begin : gen_int_logic
            logic is_level_mode;
            logic edge_detected;
            logic raw_active;

            // Type Configuration: 0 = Level Sensitive, 1 = Edge Sensitive
            assign is_level_mode = reg_int_type[i];

            // Edge Detection: XOR detects any transition (rising or falling)
            assign edge_detected = (sync_d2[i] ^ edge_latch[i]);

            // Determine active condition based on mode
            assign raw_active = is_level_mode ? edge_detected : sync_d2[i];

            // Polarity Configuration: 0 = Active High, 1 = Active Low
            // Logical OR with enable mask
            assign gpio_int[i] = (raw_active ^ reg_int_pol[i]) & reg_int_en[i];
        end
    endgenerate

    // Combined Interrupt Signal (Logical OR of all enabled interrupts)
    assign comb_int = |gpio_int;

    // =========================================================================
    // APB Response Signals
    // =========================================================================
    assign pready  = 1'b1;  // Always ready, no wait states
    assign pslverr = 1'b0;  // Error-free operation

endmodule

`endif

output.rtl/APBGlobalHistoryRegister.v:
// rtl/APBGlobalHistoryRegister.v

module APBGlobalHistoryRegister (
    input  wire pclk,
    input  wire presetn,
    input  wire [9:0] paddr,
    input  wire pselx,
    input  wire penable,
    input  wire pwrite,
    input  wire [7:0] pwdata,
    output reg  pready,
    output reg  [7:0] prdata,
    output reg  pslverr,
    input  wire history_shift_valid,
    input  wire clk_gate_en,
    output wire history_full,
    output wire history_empty,
    output wire error_flag,
    output wire interrupt_full,
    output wire interrupt_error
);

    // ---------------------------------------------------------
    // Clock Gating Logic
    // ---------------------------------------------------------
    // Samples clk_gate_en on negative edge of pclk to prevent glitches
    reg clk_gate_en_d;
    always @(negedge pclk or negedge presetn) begin
        if (!presetn)
            clk_gate_en_d <= 1'b0;
        else
            clk_gate_en_d <= clk_gate_en;
    end
    wire pclk_gated = pclk & clk_gate_en_d;

    // ---------------------------------------------------------
    // Internal State Registers
    // ---------------------------------------------------------
    reg [7:0] control_register;
    reg [7:0] train_history;
    reg [7:0] predict_history;

    reg apb_ack;

    // ---------------------------------------------------------
    // APB Interface & Register Access Logic
    // ---------------------------------------------------------
    always @(posedge pclk_gated or negedge presetn) begin
        if (!presetn) begin
            apb_ack   <= 1'b0;
            pready    <= 1'b0;
            pslverr   <= 1'b0;
            prdata    <= 8'b0;
            control_register <= 8'b0;
            train_history      <= 8'b0;
            predict_history    <= 8'b0;
        end else begin
            if (pselx && !penable) begin
                apb_ack <= 1'b1;
                pready  <= 1'b0;
            end else if (pselx && penable && apb_ack) begin
                apb_ack <= 1'b0;
                pready  <= 1'b1;

                // Address Decoding & Error Handling
                if (paddr != 10'h000 && paddr != 10'h001 && paddr != 10'h002) begin
                    pslverr <= 1'b1;
                end else begin
                    pslverr <= 1'b0;

                    if (pwrite) begin
                        // Write Operations
                        case (paddr)
                            10'h000: control_register <= pwdata;
                            10'h001: train_history    <= pwdata;
                            10'h002: ; // predict_history is read-only, ignore write
                            default: ;
                        endcase
                    end else begin
                        // Read Operations
                        case (paddr)
                            10'h000: prdata <= {4'b0000, control_register[3:0]}; // Reserved bits read 0
                            10'h001: prdata <= {1'b0, train_history[6:0]};       // Reserved bit read 0
                            10'h002: prdata <= predict_history;                  // Shift register state
                            default: prdata <= 8'b0;
                        endcase
                    end
                end
            end else begin
                apb_ack <= 1'b0;
                pready  <= 1'b0;
                pslverr <= 1'b0;
            end
        end
    end

    // ---------------------------------------------------------
    // Prediction Update Logic (Synchronous to history_shift_valid)
    // ---------------------------------------------------------
    // Updates on rising edge of history_shift_valid
    // Priority: Misprediction > Normal Prediction
    always @(posedge history_shift_valid or negedge presetn) begin
        if (!presetn) begin
            predict_history <= 8'b0;
        end else begin
            if (control_register[2]) begin // train_mispredicted has highest priority
                // Load train_history[6:0] concatenated with train_taken (control_register[3])
                predict_history <= {train_history[6:0], control_register[3]};
            end else if (control_register[0]) begin // predict_valid
                // Shift left, insert predict_taken (control_register[1]) at LSB
                predict_history <= {predict_history[7:1], control_register[1]};
            end
        end
    end

    // ---------------------------------------------------------
    // Status & Interrupt Signals
    // ---------------------------------------------------------
    assign history_full   = (predict_history == 8'hFF);
    assign history_empty  = (predict_history == 8'h00);
    assign error_flag     = pslverr;
    assign interrupt_full = history_full;
    assign interrupt_error= error_flag;

endmodule

