// rtl/axi_register.sv
module axi_register #(
    parameter int unsigned ADDR_WIDTH = 32,
    parameter int unsigned DATA_WIDTH = 32
)(
    input  logic                             clk_i,
    input  logic                             rst_n_i,
    input  logic [ADDR_WIDTH-1:0]            awaddr_i,
    input  logic                             awvalid_i,
    output logic                             awready_o,
    input  logic [DATA_WIDTH-1:0]            wdata_i,
    input  logic                             wvalid_i,
    output logic                             wready_o,
    input  logic [(DATA_WIDTH/8)-1:0]        wstrb_i,
    input  logic                             bready_i,
    output logic [1:0]                       bresp_o,
    output logic                             bvalid_o,
    input  logic [ADDR_WIDTH-1:0]            araddr_i,
    input  logic                             arvalid_i,
    output logic                             arready_o,
    output logic [DATA_WIDTH-1:0]            rdata_o,
    output logic                             rvalid_o,
    output logic [1:0]                       rresp_o,
    input  logic                             done_i,
    output logic [19:0]                      beat_o,
    output logic                             start_o,
    output logic                             writeback_o
);

    // Internal register storage
    logic [19:0] beat_reg;
    logic        start_reg;
    logic        done_reg;
    logic        writeback_reg;

    // FSM State Definitions
    localparam [2:0] WR_IDLE = 3'b000, WR_AW = 3'b001, WR_W = 3'b010, WR_B = 3'b011;
    localparam [2:0] RD_IDLE = 3'b000, RD_AR = 3'b001, RD_R = 3'b010;

    logic [2:0] wr_state, rd_state;
    logic [ADDR_WIDTH-1:0] awaddr_q, araddr_q;
    logic [1:0] bresp_q, rresp_q;

    // Local parameters for address decoding and byte width
    localparam int unsigned BYTE_WIDTH = DATA_WIDTH / 8;

    // Address decoding logic
    logic [ADDR_WIDTH-1:0] wr_addr_dec = awaddr_q;
    logic [ADDR_WIDTH-1:0] rd_addr_dec = araddr_q;

    logic is_wr_valid, is_wr_ro, is_rd_valid;
    logic full_write;

    assign full_write = (wstrb_i == {BYTE_WIDTH{1'b1}});

    assign is_wr_valid = (wr_addr_dec[ADDR_WIDTH-1:8] == 8'h01) |
                         (wr_addr_dec[ADDR_WIDTH-1:8] == 8'h02) |
                         (wr_addr_dec[ADDR_WIDTH-1:8] == 8'h03) |
                         (wr_addr_dec[ADDR_WIDTH-1:8] == 8'h04);

    assign is_wr_ro = (wr_addr_dec[ADDR_WIDTH-1:8] == 8'h05);

    assign is_rd_valid = is_wr_valid | (rd_addr_dec[ADDR_WIDTH-1:8] == 8'h05);

    // Register Update Logic
    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            beat_reg     <= 20'b0;
            start_reg    <= 1'b0;
            done_reg     <= 1'b0;
            writeback_reg<= 1'b0;
        end else begin
            // External hardware completion signal sets done status
            done_reg <= done_i;

            // Apply write to registers only when full write is performed
            if (wvalid_i && wready_o && full_write) begin
                case (awaddr_q[ADDR_WIDTH-1:8])
                    8'h01: beat_reg     <= wdata_i[19:0];
                    8'h02: start_reg    <= wdata_i[0];
                    8'h03: done_reg     <= ~wdata_i[0];
                    8'h04: writeback_reg<= wdata_i[0];
                    default: ;
                endcase
            end
        end
    end

    // AXI4-Lite FSM and Handshaking
    always_ff @(posedge clk_i or negedge rst_n_i) begin
        if (!rst_n_i) begin
            wr_state    <= WR_IDLE;
            rd_state    <= RD_IDLE;
            awready_o   <= 1'b0;
            wready_o    <= 1'b0;
            bvalid_o    <= 1'b0;
            arready_o   <= 1'b0;
            rvalid_o    <= 1'b0;
            bresp_q     <= 2'b00;
            rresp_q     <= 2'b00;
        end else begin
            // Write FSM
            case (wr_state)
                WR_IDLE: begin
                    awready_o <= awvalid_i;
                    if (awvalid_i) wr_state <= WR_AW;
                end
                WR_AW: begin
                    awready_o <= 1'b0;
                    wready_o  <= 1'b0;
                    awaddr_q  <= awaddr_i;
                    if (wvalid_i) wr_state <= WR_W;
                end
                WR_W: begin
                    wready_o  <= 1'b1;
                    if (wvalid_i) begin
                        bresp_q <= (is_wr_valid && ~is_wr_ro) ? 2'b00 : 2'b10;
                        wr_state <= WR_B;
                    end
                end
                WR_B: begin
                    bvalid_o  <= 1'b1;
                    if (bvalid_o && bready_i) begin
                        bvalid_o <= 1'b0;
                        wr_state <= WR_IDLE;
                    end
                end
            endcase

            // Read FSM
            case (rd_state)
                RD_IDLE: begin
                    arready_o <= arvalid_i;
                    if (arvalid_i) rd_state <= RD_AR;
                end
                RD_AR: begin
                    arready_o <= 1'b0;
                    araddr_q  <= araddr_i;
                    rresp_q   <= is_rd_valid ? 2'b00 : 2'b10;
                    rd_state  <= RD_R;
                end
                RD_R: begin
                    rvalid_o  <= 1'b1;
                    if (rvalid_o && rready_i) begin
                        rvalid_o <= 1'b0;
                        rd_state <= RD_IDLE;
                    end
                end
            endcase
            bresp_o <= bresp_q;
            rresp_o <= rresp_q;
        end
    end

    // Read Data Mux
    always_comb begin
        unique case (araddr_i[ADDR_WIDTH-1:8])
            8'h01: rdata_o = {DATA_WIDTH-20{1'b0}, beat_reg};
            8'h02: rdata_o = {DATA_WIDTH-1{1'b0}, start_reg};
            8'h03: rdata_o = {DATA_WIDTH-1{1'b0}, done_reg};
            8'h04: rdata_o = {DATA_WIDTH-1{1'b0}, writeback_reg};
            8'h05: rdata_o = 32'h00010001;
            default: rdata_o = '0;
        endcase
    end

    // Output Assignments
    assign beat_o     = beat_reg;
    assign start_o    = start_reg;
    assign writeback_o= writeback_reg;

endmodule

output.rtl/axis_upscale.sv:
module axis_upscale (
    input  logic        clk,
    input  logic        resetn,
    input  logic        dfmt_enable,
    input  logic        dfmt_type,
    input  logic        dfmt_se,
    input  logic        s_axis_valid,
    input  logic [23:0] s_axis_data,
    input  logic        m_axis_ready,
    output logic        s_axis_ready,
    output logic        m_axis_valid,
    output logic [31:0] m_axis_data
);

    logic [7:0] ext_bits;
    logic       sel_bit;

    // Determine the extension bit based on data format control signals
    always_comb begin
        if (!dfmt_enable) begin
            sel_bit = 1'b0;
        end else if (dfmt_se) begin
            sel_bit = s_axis_data[23]; // Sign extension (23rd bit)
        end else if (dfmt_type) begin
            sel_bit = ~s_axis_data[23]; // Inverted MSB carry forward
        end else begin
            sel_bit = 1'b0; // Zero extension
        end
        ext_bits = {8{sel_bit}};
    end

    // AXI Stream handshaking signals
    assign s_axis_ready = m_axis_ready;
    assign m_axis_valid = s_axis_valid;

    // Single pipeline register stage for output data with active-low synchronous reset
    always_ff @(posedge clk) begin
        if (!resetn) begin
            m_axis_data <= 32'b0;
        end else begin
            m_axis_data <= {ext_bits, s_axis_data};
        end
    end

endmodule

output.rtl/precision_counter_axi.sv:
module precision_counter_axi #(
    parameter integer C_S_AXI_DATA_WIDTH = 32,
    parameter integer C_S_AXI_ADDR_WIDTH = 8
)(
    input  wire                     axi_aclk,
    input  wire                     axi_aresetn,
    // Write address channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0] axi_awaddr,
    input  wire                     axi_awvalid,
    output wire                    axi_awready,
    // Write data channel
    input  wire [C_S_AXI_DATA_WIDTH-1:0] axi_wdata,
    input  wire [(C_S_AXI_DATA_WIDTH/8)-1:0] axi_wstrb,
    input  wire                     axi_wvalid,
    output wire                    axi_wready,
    // Write response channel
    output wire [1:0]             axi_bresp,
    output wire                   axi_bvalid,
    input  wire                   axi_bready,
    // Read address channel
    input  wire [C_S_AXI_ADDR_WIDTH-1:0] axi_araddr,
    input  wire                   axi_arvalid,
    output wire                  axi_arready,
    // Read response channel
    output wire [C_S_AXI_DATA_WIDTH-1:0] axi_rdata,
    output wire [1:0]             axi_rresp,
    output wire                   axi_rvalid,
    input  wire                   axi_rready,
    // Control outputs
    output wire                   axi_ap_done,
    output wire                   irq
);

localparam [2:0] IDLE_S = 3'b000;
localparam [2:0] WADDR_S = 3'b001;
localparam [2:0] WDATA_S = 3'b010;
localparam [2:0] RADDR_S = 3'b011;

logic [2:0] fsm_state;
logic [C_S_AXI_ADDR_WIDTH-1:0] slv_reg_addr;
logic [C_S_AXI_DATA_WIDTH-1:0] slv_reg_wdata;
logic [(C_S_AXI_DATA_WIDTH/8)-1:0] slv_reg_wstrb;
logic aw_ready;
logic w_ready;
logic b_valid;
logic ar_ready;
logic r_valid;

// Internal registers
logic [31:0] reg_ctl;
logic [31:0] reg_t;
logic [31:0] reg_v;
logic [31:0] reg_irq_mask;
logic [31:0] reg_irq_thresh;
logic ap_done_int;
logic irq_int;

// AXI Ready/Valid assignments
assign axi_awready = (fsm_state == IDLE_S) ? aw_ready : 1'b0;
assign axi_wready  = (fsm_state == WADDR_S) ? w_ready : 1'b0;
assign axi_bvalid  = (fsm_state == WDATA_S) ? b_valid : 1'b0;
assign axi_arready = (fsm_state == IDLE_S) ? ar_ready : 1'b0;
assign axi_rvalid  = (fsm_state == RADDR_S) ? r_valid : 1'b0;

// FSM for AXI Handshaking
always @(posedge axi_aclk or negedge axi_aresetn) begin
    if (!axi_aresetn) begin
        fsm_state <= IDLE_S;
        aw_ready <= 1'b0;
        w_ready <= 1'b0;
        b_valid <= 1'b0;
        ar_ready <= 1'b0;
        r_valid <= 1'b0;
    end else begin
        aw_ready <= 1'b0;
        w_ready <= 1'b0;
        b_valid <= 1'b0;
        ar_ready <= 1'b0;
        r_valid <= 1'b0;

        case (fsm_state)
            IDLE_S: begin
                if (axi_awvalid) begin
                    aw_ready <= 1'b1;
                    if (axi_awvalid && aw_ready) begin
                        slv_reg_addr <= axi_awaddr;
                        fsm_state <= WADDR_S;
                    end
                end else if (axi_arvalid) begin
                    ar_ready <= 1'b1;
                    if (axi_arvalid && ar_ready) begin
                        slv_reg_addr <= axi_araddr;
                        fsm_state <= RADDR_S;
                    end
                end
            end
            WADDR_S: begin
                w_ready <= 1'b1;
                if (axi_wvalid && w_ready) begin
                    slv_reg_wdata <= axi_wdata;
                    slv_reg_wstrb <= axi_wstrb;
                    fsm_state <= WDATA_S;
                end
            end
            WDATA_S: begin
                b_valid <= 1'b1;
                if (axi_bready && b_valid) begin
                    fsm_state <= IDLE_S;
                end
            end
            RADDR_S: begin
                r_valid <= 1'b1;
                if (axi_rready && r_valid) begin
                    fsm_state <= IDLE_S;
                end
            end
            default: fsm_state <= IDLE_S;
        endcase
    end
end

// Register Update Logic
always @(posedge axi_aclk or negedge axi_aresetn) begin
    if (!axi_aresetn) begin
        reg_ctl <= 0;
        reg_t <= 0;
        reg_v <= 0;
        reg_irq_mask <= 0;
        reg_irq_thresh <= 0;
    end else begin
        if (fsm_state == WDATA_S && axi_bready && b_valid) begin
            case (slv_reg_addr)
                8'h00: begin
                    if (slv_reg_wstrb[0]) reg_ctl[ 7: 0] <= slv_reg_wdata[ 7: 0];
                    if (slv_reg_wstrb[1]) reg_ctl[15: 8] <= slv_reg_wdata[15: 8];
                    if (slv_reg_wstrb[2]) reg_ctl[23:16] <= slv_reg_wdata[23:16];
                    if (slv_reg_wstrb[3]) reg_ctl[31:24] <= slv_reg_wdata[31:24];
                    reg_t <= 0; // Reset elapsed time on write to control register
                end
                8'h10: begin
                    if (slv_reg_wstrb[0]) reg_t[ 7: 0] <= slv_reg_wdata[ 7: 0];
                    if (slv_reg_wstrb[1]) reg_t[15: 8] <= slv_reg_wdata[15: 8];
                    if (slv_reg_wstrb[2]) reg_t[23:16] <= slv_reg_wdata[23:16];
                    if (slv_reg_wstrb[3]) reg_t[31:24] <= slv_reg_wdata[31:24];
                end
                8'h20: begin
                    if (slv_reg_wstrb[0]) reg_v[ 7: 0] <= slv_reg_wdata[ 7: 0];
                    if (slv_reg_wstrb[1]) reg_v[15: 8] <= slv_reg_wdata[15: 8];
                    if (slv_reg_wstrb[2]) reg_v[23:16] <= slv_reg_wdata[23:16];
                    if (slv_reg_wstrb[3]) reg_v[31:24] <= slv_reg_wdata[31:24];
                end
                8'h24: begin
                    if (slv_reg_wstrb[0]) reg_irq_mask[ 7: 0] <= slv_reg_wdata[ 7: 0];
                    if (slv_reg_wstrb[1]) reg_irq_mask[15: 8] <= slv_reg_wdata[15: 8];
                    if (slv_reg_wstrb[2]) reg_irq_mask[23:16] <= slv_reg_wdata[23:16];
                    if (slv_reg_wstrb[3]) reg_irq_mask[31:24] <= slv_reg_wdata[31:24];
                end
                8'h28: begin
                    if (slv_reg_wstrb[0]) reg_irq_thresh[ 7: 0] <= slv_reg_wdata[ 7: 0];
                    if (slv_reg_wstrb[1]) reg_irq_thresh[15: 8] <= slv_reg_wdata[15: 8];
                    if (slv_reg_wstrb[2]) reg_irq_thresh[23:16] <= slv_reg_wdata[23:16];
                    if (slv_reg_wstrb[3]) reg_irq_thresh[31:24] <= slv_reg_wdata[31:24];
                end
                default: ; // Ignore writes to undefined addresses
            endcase
        end
    end
end

// Countdown Logic
always @(posedge axi_aclk or negedge axi_aresetn) begin
    if (!axi_aresetn) begin
        ap_done_int <= 1'b0;
    end else begin
        if (reg_ctl[0]) begin // Counter running
            if (reg_v > 0) begin
                reg_v <= reg_v - 1;
                ap_done_int <= 1'b0;
            end else begin
                ap_done_int <= 1'b1; // Countdown reached zero
            end
        end else begin
            ap_done_int <= 1'b0; // Counter stopped
        end
    end
end

// Elapsed Time Logic
always @(posedge axi_aclk or negedge axi_aresetn) begin
    if (!axi_aresetn) begin
        reg_t <= 0;
    end else begin
        // Increment only when countdown is finished
        if (ap_done_int) begin
            reg_t <= reg_t + 1;
        end
    end
end

// Interrupt Logic
always @(posedge axi_aclk or negedge axi_aresetn) begin
    if (!axi_aresetn) begin
        irq_int <= 1'b0;
    end else begin
        // Asserted when mask is enabled and current value matches threshold
        if (reg_ctl[0] == 0) begin
            irq_int <= 1'b0;
        end else if (reg_irq_mask[0] && (reg_v == reg_irq_thresh)) begin
            irq_int <= 1'b1;
        end else begin
            irq_int <= 1'b0;
        end
    end
end

// Read Data Mux & Response Registration
logic [C_S_AXI_DATA_WIDTH-1:0] r_data_reg;
logic [1:0] r_resp_reg;
always @(posedge axi_aclk) begin
    if (fsm_state == RADDR_S) begin
        r_data_reg <= (slv_reg_addr == 8'h00) ? reg_ctl :
                      (slv_reg_addr == 8'h10) ? reg_t :
                      (slv_reg_addr == 8'h20) ? reg_v :
                      (slv_reg_addr == 8'h24) ? reg_irq_mask :
                      (slv_reg_addr == 8'h28) ? reg_irq_thresh : 0;
        r_resp_reg <= (slv_reg_addr == 8'h00 || slv_reg_addr == 8'h10 || slv_reg_addr == 8'h20 || slv_reg_addr == 8'h24 || slv_reg_addr == 8'h28) ? 2'b00 : 2'b10;
    end
end
assign axi_rdata = r_data_reg;
assign axi_rresp = r_resp_reg;

// Write Response Registration
logic [1:0] b_resp_reg;
always @(posedge axi_aclk) begin
    if (fsm_state == WDATA_S) begin
        b_resp_reg <= (slv_reg_addr == 8'h00 || slv_reg_addr == 8'h10 || slv_reg_addr == 8'h20 || slv_reg_addr == 8'h24 || slv_reg_addr == 8'h28) ? 2'b00 : 2'b10;
    end
end
assign axi_bresp = b_resp_reg;

assign axi_ap_done = ap_done_int;
assign irq = irq_int;

endmodule

output.rtl/axis_joiner.sv:
module axis_joiner (
    input  logic                    clk,
    input  logic                    rst,
    // Stream 1
    input  logic [7:0]              s_axis_tdata_1,
    input  logic                    s_axis_tvalid_1,
    output logic                    s_axis_tready_1,
    input  logic                    s_axis_tlast_1,
    // Stream 2
    input  logic [7:0]              s_axis_tdata_2,
    input  logic                    s_axis_tvalid_2,
    output logic                    s_axis_tready_2,
    input  logic                    s_axis_tlast_2,
    // Stream 3
    input  logic [7:0]              s_axis_tdata_3,
    input  logic                    s_axis_tvalid_3,
    output logic                    s_axis_tready_3,
    input  logic                    s_axis_tlast_3,
    // Merged Output
    output logic [7:0]              m_axis_tdata,
    output logic                    m_axis_tvalid,
    input  logic                    m_axis_tready,
    output logic                    m_axis_tlast,
    output logic [1:0]              m_axis_tuser,
    // Status
    output logic                    busy
);

    // FSM State Definitions
    typedef enum logic [1:0] {
        STATE_IDLE = 2'b00,
        STATE_1    = 2'b01,
        STATE_2    = 2'b10,
        STATE_3    = 2'b11
    } state_t;

    state_t state, next_state;

    // Internal output registers for seamless buffering
    logic [7:0] m_tdata_reg;
    logic       m_tlast_reg;
    logic [1:0] m_tuser_reg;
    logic       temp; // Stall/hold indicator flag

    // Combinational MUX outputs based on current state
    logic [7:0] muxed_data;
    logic       muxed_last;
    logic [1:0] muxed_user;

    // Data Selection MUX
    always_comb begin
        case (state)
            STATE_IDLE: begin
                muxed_data  = 8'b0;
                muxed_last  = 1'b0;
                muxed_user  = 2'b00;
            end
            STATE_1: begin
                muxed_data  = s_axis_tdata_1;
                muxed_last  = s_axis_tlast_1;
                muxed_user  = 2'b01; // TAG_ID_1 = 0x1
            end
            STATE_2: begin
                muxed_data  = s_axis_tdata_2;
                muxed_last  = s_axis_tlast_2;
                muxed_user  = 2'b10; // TAG_ID_2 = 0x2
            end
            STATE_3: begin
                muxed_data  = s_axis_tdata_3;
                muxed_last  = s_axis_tlast_3;
                muxed_user  = 2'b11; // TAG_ID_3 = 0x3
            end
            default: begin
                muxed_data  = 8'b0;
                muxed_last  = 1'b0;
                muxed_user  = 2'b00;
            end
        endcase
    end

    // Output Register Updates & Buffering Logic
    // Retains data when m_axis_tready is deasserted (temp flag asserted)
    always_ff @(posedge clk or posedge rst) begin
        if (rst) begin
            m_tdata_reg   <= 8'b0;
            m_tlast_reg   <= 1'b0;
            m_tuser_reg   <= 2'b00;
            temp          <= 1'b0;
        end else begin
            if (m_axis_tready) begin
                // Downstream ready: update registers with current stream data
                m_tdata_reg   <= muxed_data;
                m_tlast_reg   <= muxed_last;
                m_tuser_reg   <= muxed_user;
                temp          <= 1'b0; // Clear stall flag on successful transfer
            end else if (state != STATE_IDLE) begin
                // Downstream stalled: hold previous data, assert temp flag
                temp          <= 1'b1;
            end
        end
    end

    // Assign Merged Output Ports
    assign m_axis_tdata  = m_tdata_reg;
    assign m_axis_tlast  = m_tlast_reg;
    assign m_axis_tuser  = m_tuser_reg;
    assign m_axis_tvalid = (state != STATE_IDLE);

    // Input Ready Signals: Only acknowledge the active stream and only if downstream is ready
    assign s_axis_tready_1 = (state == STATE_1) && m_axis_tready;
    assign s_axis_tready_2 = (state == STATE_2) && m_axis_tready;
    assign s_axis_tready_3 = (state == STATE_3) && m_axis_tready;

    // Busy Status Indicator
    assign busy = (state != STATE_IDLE);

    // FSM State Flip-Flops
    always_ff @(posedge clk or posedge rst) begin
        if (rst)
            state <= STATE_IDLE;
        else
            state <= next_state;
    end

    // Next State Logic (Priority: 1 > 2 > 3)
    always_comb begin
        next_state = state;
        case (state)
            STATE_IDLE: begin
                if (s_axis_tvalid_1)
                    next_state = STATE_1;
                else if (s_axis_tvalid_2)
                    next_state = STATE_2;
                else if (s_axis_tvalid_3)
                    next_state = STATE_3;
            end
            STATE_1: begin
                if (m_axis_tready && s_axis_tlast_1)
                    next_state = STATE_IDLE;
            end
            STATE_2: begin
                if (m_axis_tready && s_axis_tlast_2)
                    next_state = STATE_IDLE;
            end
            STATE_3: begin
                if (m_axis_tready && s_axis_tlast_3)
                    next_state = STATE_IDLE;
            end
            default:
                next_state = STATE_IDLE;
        endcase
    end

endmodule

output.rtl/bcd_counter.sv:
module bcd_counter (
    input  wire clk,
    input  wire rst,
    output logic [3:0] ms_hr,
    output logic [3:0] ls_hr,
    output logic [3:0] ms_min,
    output logic [3:0] ls_min,
    output logic [3:0] ms_sec,
    output logic [3:0] ls_sec
);

    // Internal registers for each BCD digit
    logic [3:0] sec_l, sec_m;
    logic [3:0] min_l, min_m;
    logic [3:0] hr_l,  hr_m;

    always @(posedge clk) begin
        if (rst) begin
            // Synchronous active-high reset
            sec_l <= 4'd0; sec_m <= 4'd0;
            min_l <= 4'd0; min_m <= 4'd0;
            hr_l  <= 4'd0; hr_m  <= 4'd0;
        end else begin
            // Seconds Counter (00-59)
            sec_l <= (sec_l == 4'd9) ? 4'd0 : sec_l + 1'b1;
            sec_m <= (sec_m == 4'd5) ? 4'd0 : (sec_l == 4'd9 ? sec_m + 1'b1 : sec_m);

            // Minutes Counter (00-59)
            min_l <= (min_l == 4'd9) ? 4'd0 : (sec_m == 4'd5 ? min_l + 1'b1 : min_l);
            min_m <= (min_m == 4'd5) ? 4'd0 : (min_l == 4'd9 ? min_m + 1'b1 : min_m);

            // Hours Counter (00-23)
            // hr_l resets to 0 at 9, or at 3 when ms_hr is 2
            hr_l  <= (hr_l == 4'd9 || (hr_m == 4'd2 && hr_l == 4'd3)) ? 4'd0 : hr_l + 1'b1;
            // hr_m resets to 0 when hour rolls from 23->00, otherwise increments on hr_l rollover
            hr_m  <= (hr_m == 4'd2 && hr_l == 4'd3) ? 4'd0 : 
                     (hr_l == 4'd9 || (hr_m == 4'd2 && hr_l == 4'd3)) ? hr_m + 1'b1 : hr_m;
        end
    end

    // Map internal registers to module outputs
    assign ls_sec = sec_l;
    assign ms_sec = sec_m;
    assign ls_min = min_l;
    assign ms_min = min_m;
    assign ls_hr  = hr_l;
    assign ms_hr  = hr_m;

endmodule

output.rtl/bcd_to_excess_3.sv:
module bcd_to_excess_3 (
    input  logic [3:0] bcd,
    output logic [3:0] excess3,
    output logic       error
);

    always_comb begin
        if (bcd >= 4'd10) begin
            excess3 = 4'b0000;
            error   = 1'b1;
        end else begin
            excess3 = bcd + 3'd3;
            error   = 1'b0;
        end
    end

endmodule

output.rtl/binary_to_one_hot_decoder.v:
`timescale 1ns / 1ps

module binary_to_one_hot_decoder (
    input  wire [BINARY_WIDTH-1:0] binary_in,
    output wire [OUTPUT_WIDTH-1:0] one_hot_out
);
    parameter BINARY_WIDTH  = 5;
    parameter OUTPUT_WIDTH  = 32;

    // Combinational binary to one-hot decoder
    // If binary_in is within OUTPUT_WIDTH bounds, the corresponding bit is set to 1.
    // If binary_in is out of range (>= OUTPUT_WIDTH), the output is all zeros.
    assign one_hot_out = (binary_in < OUTPUT_WIDTH) ? (1 << binary_in) : '0;

endmodule

